// Low-frequency, resistive support models; never a safety certification.
const num=(x,label,zero=false)=>{const s=String(x??'').trim();if(!/^[+]?(?:\d+(?:[.,]\d*)?|[.,]\d+)(?:e[+-]?\d+)?$/i.test(s))throw Error(`${label}: informe número válido não negativo.`);const n=Number(s.replace(',','.'));if(!Number.isFinite(n)||(zero?n<0:n<=0))throw Error(`${label}: valor fora do domínio.`);return n;};
const row=(label,value,unit='')=>({label,value,unit});
export function calculateGrounding(id,x){
 let values,formula,steps,note;const warnings=[];
 switch(id){
 case 'earth-wenner':{
  const a=num(x.a,'Espaçamento'),r=num(x.r,'Leitura'),b=num(x.b,'Penetração',true);if(b>a/20)throw Error('Este modelo raso exige penetração b ≤ a/20. Aumente o espaçamento ou use modelo com correção de profundidade.');const rho=2*Math.PI*a*r;
  values=[row('Resistividade aparente',rho,'Ω·m'),row('Resistividade aparente',rho*100,'Ω·cm'),row('Razão penetração / espaçamento',100*b/a,'%')];formula='ρa ≈ 2πaR, para b ≤ a/20';steps=[`ρa = 2π × ${a} × ${r}`,`b/a = ${b}/${a}; Ω·cm = 100 × Ω·m`];note='Quatro sondas alinhadas e igualmente espaçadas; corrente nas externas, potencial nas internas. Aproximação de sondas rasas em meio isotrópico. R é a leitura V/I do ensaio Wenner, não a resistência de um eletrodo instalado. Uma medida não identifica camadas nem uma profundidade exata; compare espaçamentos e direções, sazonalidade, interferências e incerteza instrumental.';break;
 }
 case 'earth-electrodes':{
  const rho=num(x.rho,'Resistividade'),l=num(x.l,'Comprimento de haste'),n=num(x.n,'Quantidade de hastes'),spacing=num(x.spacing,'Espaçamento'),ring=num(x.ring,'Comprimento do anel');if(!Number.isInteger(n)||n>10000)throw Error('Quantidade deve ser inteira de 1 a 10.000.');if(n>1&&spacing<=4*l)throw Error('A aproximação R/n exige espaçamento maior que 4L entre hastes. Não divida por n para hastes próximas.');
  values=[row('Conjunto de hastes · aproximação',rho/(n*l),'Ω'),row('Uma haste · aproximação',rho/l,'Ω'),row('Anel enterrado · aproximação',2*rho/ring,'Ω'),row('Espaçamento / comprimento',spacing/l,'')];formula='Rhaste ≈ ρ/L; Rn ≈ ρ/(nL), espaçamento > 4L; Ranel ≈ 2ρ/Lanel';steps=[`Rn ≈ ${rho}/(${n} × ${l})`,`Ranel ≈ 2 × ${rho}/${ring}`];note='Comparação preliminar em solo homogêneo: hastes verticais idênticas e anel nu em contato direto com o solo. Os resultados são alternativas separadas; não representam a resistência de hastes mais anel interligados. Aproximações de ordem de grandeza não incluem diâmetro, profundidade do anel, camadas, resistências mútuas, corrosão ou impedância impulsiva. Valide a geometria com modelo adequado e medição; não é análise de malha nem SPDA.';break;
 }
 case 'earth-tt':{
  const ra=num(x.ra,'RA'),rb=num(x.rb,'RB'),v=num(x.v,'Tensão fase-terra'),dr=num(x.dr,'IΔn')/1000,limit=num(x.limit,'Limite de tensão');const product=ra*dr,imax=limit/ra,ramax=limit/dr,fault=v/(ra+rb),uf=fault*ra;
  values=[row('Produto RA × IΔn',product,'V'),row('RA máximo pela relação informada',ramax,'Ω'),row('IΔn máximo pela relação informada',imax*1000,'mA'),row('Corrente de falta TT simplificada',fault,'A'),row('Potencial da massa antes do desligamento',uf,'V'),row('Margem na relação RA × IΔn',limit-product,'V')];formula='RA × IΔn ≤ UL; RAmax = UL/IΔn; Id ≈ U0/(RA+RB); Uf ≈ RA × Id';steps=[`RA × IΔn = ${ra} × ${dr}`,`Id ≈ ${v}/(${ra}+${rb}); Uf ≈ ${ra} × ${fault}`];note='Somente esquema TT, circuito resistivo simplificado e falta franca. RA representa resistência total das massas ao terra (inclua o caminho de proteção); RB representa aterramento da fonte. UL é definido pelo usuário conforme a aplicação, não escolhido automaticamente. A relação com IΔn é condição parcial de coordenação; Uf é tensão durante a falta, distinta de RA×IΔn. Não verifica tempo/curva do DR, tipo de corrente residual, seletividade, continuidade do PE ou requisitos normativos.';
  if(product>limit)warnings.push('A relação RA × IΔn excede o limite informado.');else warnings.push('A relação parcial foi atendida; isso não comprova proteção completa nem tempo de desligamento.');if(fault<dr)warnings.push('A corrente de falta estimada é menor que IΔn: atuação do DR não garantida neste modelo.');break;
 }
 case 'earth-gpr':{
  const current=num(x.i,'Corrente de falta',true)*1000,split=num(x.split,'Fração pelo solo',true),r=num(x.r,'Resistência ao terra remoto');if(split>1)throw Error('Fração pelo solo deve estar entre 0 e 1.');const ig=current*split;
  values=[row('Elevação de potencial GPR',ig*r,'V'),row('Corrente efetiva pelo solo',ig/1000,'kA'),row('Corrente por outros retornos',current*(1-split)/1000,'kA')];formula='IG = If × Sf; GPR ≈ IG × Rg';steps=[`IG = ${current} × ${split} A`,`GPR ≈ ${ig} × ${r} V`];note='Modelo resistivo em baixa frequência, com valores RMS e fração de corrente fornecida por estudo externo. Rg é a resistência do sistema ao terra remoto. Não estima Sf a partir da geometria, nem fator de decremento, assimetria, potencial transferido ou impulso de raio. GPR não equivale à tensão de toque nem à de passo; estas dependem dos potenciais locais, geometria, tempo, superfície e trajetos de contato. Nenhum valor é classificado automaticamente como seguro.';warnings.push('GPR não é tensão de toque ou de passo. É necessário estudo dos potenciais locais.');break;
 }
 case 'earth-fop':{
  const d=num(x.d,'Distância E-H'),r52=num(x.r52,'R52'),r62=num(x.r62,'R62'),r72=num(x.r72,'R72'),tol=num(x.tol,'Tolerância',true);if(tol>100)throw Error('Tolerância deve estar entre 0 e 100%.');const spread=100*Math.max(Math.abs(r52-r62),Math.abs(r72-r62))/r62;
  values=[row('Leitura central R62 · sem validação automática',r62,'Ω'),row('Maior desvio relativo a R62',spread,'%'),row('Posição S em 52%',.52*d,'m'),row('Posição S em 62%',.62*d,'m'),row('Posição S em 72%',.72*d,'m')];formula='Desvio = 100 × max(|R52−R62|, |R72−R62|)/R62; posição S = fração × D';steps=[`Desvio = 100 × max(|${r52}−${r62}|,|${r72}−${r62}|)/${r62}`,`Posições = (0,52; 0,62; 0,72) × ${d} m`];note='Análise de três leituras de queda de potencial; E é o sistema ensaiado, H a sonda de corrente e S a de potencial. A tolerância é um critério de comparação definido pelo usuário, não um limite normativo. Leituras próximas apenas sugerem trecho plano: não garantem distância suficiente, solo homogêneo, isolamento de retornos ou ausência de interferência. A regra de 62% é limitada a geometrias simples; sistemas extensos requerem curva completa e método apropriado. Não desconecte aterramentos de instalação energizada para realizar este ensaio.';warnings.push(spread>tol?'Dispersão acima do critério informado. Revise o ensaio e a curva.':'Dispersão dentro do critério informado; a validade do ensaio ainda precisa ser verificada.');break;
 }
 default:return null;
 }
 if(values.some(v=>!Number.isFinite(v.value)))throw Error('Valores excedem o intervalo numérico.');return {id,values,formula,steps,note,warnings};
}
